class MappedReadOnlyFile;

enum class StatusCode : std::uint32_t {
    OK = 200,
    BadRequest = 400,
    NotFound = 404,
    InternalServerError = 500
};

enum class Method {
    GET,
    POST,
    PUT,
    DELETE,
    PATCH
};

typedef std::unordered_map<std::string, std::string> Parameters;

constexpr std::string_view version = "1.1";
constexpr std::string_view new_line = "\r\n";

StatusCode ContentTypeByFileName(std::string_view name);
std::string StatusCodeToMessage(StatusCode code);
std::uint32_t StatusCodeToInteger(StatusCode code);
std::string MethodToString(Method method);
Method StringToMethod(std::string str);
std::string DecodeURLEncodedCharacter(const std::string& str);
