#include <iostream>
#include <fstream>
#include <sstream>
#include <algorithm>

namespace ws::http {

StatusCode ContentTypeByFileName(std::string_view name) {
    if (name.ends_with(".html") || name.ends_with(".htm")) {
        return StatusCode::OK;
    } else if (name.ends_with(".txt")) {
        return StatusCode::OK;
    } else if (name.ends_with(".jpg") || name.ends_with(".jpeg")) {
        return StatusCode::OK;
    } else if (name.ends_with(".png")) {
        return StatusCode::OK;
    } else {
        return StatusCode::NotFound;
    }
}

std::string StatusCodeToMessage(StatusCode code) {
    switch (code) {
        case StatusCode::OK: return "OK";
        case StatusCode::BadRequest: return "Bad Request";
        case StatusCode::NotFound: return "Not Found";
        case StatusCode::InternalServerError: return "Internal Server Error";
        default: return "Unknown Status Code";
    }
}

std::uint32_t StatusCodeToInteger(StatusCode code) {
    return static_cast<std::uint32_t>(code);
}

std::string MethodToString(Method method) {
    switch (method) {
        case Method::GET: return "GET";
        case Method::POST: return "POST";
        case Method::PUT: return "PUT";
        case Method::DELETE: return "DELETE";
        case Method::PATCH: return "PATCH";
        default: return "UNKNOWN";
    }
}

Method StringToMethod(std::string str) {
    if (str == "GET") return Method::GET;
    if (str == "POST") return Method::POST;
    if (str == "PUT") return Method::PUT;
    if (str == "DELETE") return Method::DELETE;
    if (str == "PATCH") return Method::PATCH;
    return Method::GET; // Default to GET
}

std::string DecodeURLEncodedCharacter(const std::string& str) {
    std::stringstream decoded_char;
    for (char c : str) {
        if (c == '%') {
            // Assuming hexadecimal encoding
            std::string hex_value = str.substr(1, 2);
            try {
                int char_code = std::stoi(hex_value, nullptr, 16);
                decoded_char << static_cast<char>(char_code);
            } catch (const std::invalid_argument& e) {
                // Handle invalid hex value
                return ""; // Or some error indicator
            }
        } else if (c == '+') {
            decoded_char << ' ';
        } else {
            decoded_char << c;
        }
    }
    return decoded_char.str();
}

std::string DecodeURLEncodedString(const std::string& str) {
    std::string decoded_string;
    size_t pos = 0;
    while (pos < str.length()) {
        if (str[pos] == '%') {
            decoded_string += DecodeURLEncodedCharacter(str.substr(pos, 3));
            pos += 3;
        } else if (str[pos] == '+') {
            decoded_string += ' ';
            pos++;
        } else {
            decoded_string += str[pos];
            pos++;
        }
    }
    return decoded_string;
}

std::string HTMLPlaceholder(std::string_view key) {
    return "<$" + std::string(key) + ">";
}

std::string PutParamIntoHTML(std::string html, const Parameters& params) {
    for (const auto& [key, value] : params) {
        size_t pos = 0;
        while ((pos = html.find(HTMLPlaceholder(key), pos)) != std::string::npos) {
            html.replace(pos, HTMLPlaceholder(key).length(), value);
            pos += value.length();
        }
    }
    return html;
}

}

