#ifndef WS_HTTP_RESPONSE_H
#define WS_HTTP_RESPONSE_H

#include <string>
#include <filesystem>
#include <unordered_map>
#include <optional>

namespace ws::http {

enum class StatusCode : std::uint32_t;
typedef std::unordered_map<std::string, std::string> Parameters;

class MappedReadOnlyFile;

class Response {
public:
    Response(const std::filesystem::path& root_dir);
    void Build(Buffer& buf, std::filesystem::path file, StatusCode& code);
    void Build(Buffer& buf, std::filesystem::path html, const Parameters& params, StatusCode& code);
    void Build(Buffer& buf, StatusCode code, std::string msg);

private:
    const std::filesystem::path root_dir_; // Root directory for serving files
    std::filesystem::path file_path_;       // Path to the file being served (if any)
    MappedReadOnlyFile* file_;              // Mapped readonly file object
    bool keep_alive_;                       // Keep-alive flag
    StatusCode status_code_;
};

}

#endif // WS_HTTP_RESPONSE_H

#include "response.h"
#include <iostream>
// Assuming Buffer and MappedReadOnlyFile are defined elsewhere
class Buffer;
class MappedReadOnlyFile;
namespace ws::http {

Response::Response(const std::filesystem::path& root_dir) : root_dir_(root_dir), file_(nullptr), keep_alive_(false), status_code_(StatusCode::OK) {}

void Response::Build(Buffer& buf, std::filesystem::path file, StatusCode& code) {
    file_path_ = file;
    try {
        file_ = new MappedReadOnlyFile(file_path_); // Assuming constructor takes path
        code = StatusCode::OK; 
    } catch (const std::exception& e) {
        std::cerr << "Error opening file: " << e.what() << std::endl;
        code = StatusCode::NotFound;
        return;
    }

    // Send the file content to the buffer
    if(file_ != nullptr){
      buf.Write(file_->Data(), file_->Size());
    }

    delete file_; // Clean up after writing.
}

void Response::Build(Buffer& buf, std::filesystem::path html, const Parameters& params, StatusCode& code) {
    // Load the HTML template from the file
    std::ifstream file(html);
    if (!file.is_open()) {
        code = StatusCode::NotFound;
        return;
    }
    std::string html_content((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
    file.close();

    // Replace placeholders with parameters
    std::string modified_html = PutParamIntoHTML(html_content, params);

    // Write the modified HTML to the buffer
    buf.WriteString(modified_html);
    code = StatusCode::OK;
}

void Response::Build(Buffer& buf, StatusCode code, std::string msg) {
    // Build an error response with the given status code and message.
    std::string response_str = "HTTP/1.1 " + std::to_string(StatusCodeToInteger(code)) + " " + StatusCodeToMessage(code) + new_line;
    response_str += "Content-Type: text/plain" + new_line;
    response_str += new_line;
    response_str += msg + new_line;

    buf.WriteString(response_str);
}

}
